import sys

def is_palindrome(s):
    return s == s[::-1]

s = sys.stdin.readline().strip()
k = int(sys.stdin.readline().strip())

n = len(s)
if k * (n // k) != n:
    print("NO")
else:
    length = n // k
    if all(is_palindrome(s[i:i+length]) for i in range(0, n, length)):
        print("YES")
    else:
        print("NO")
